const body = $json.body ?? $json;
const lat = Number(body.lat ?? body.location?.lat);
const lng = Number(body.lng ?? body.location?.lng);
const radiusKm = Math.min(50, Math.max(0.1, Number(body.radiusKm ?? 10)));
if (!Number.isFinite(lat) || !Number.isFinite(lng) || Math.abs(lat) > 90 || Math.abs(lng) > 180) return [{ json: { ok: false, error: { code: 'INVALID_LOCATION', message: 'Coordenadas inválidas.' } } }];
const center = { lat, lng };
const haversine = (a, b) => { const r = 6371; const rad = (v) => v * Math.PI / 180; const dLat = rad(b.lat-a.lat); const dLng = rad(b.lng-a.lng); const h = Math.sin(dLat/2)**2 + Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dLng/2)**2; return r*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h)); };
const filter = (items) => (Array.isArray(items) ? items : []).filter((item) => Number.isFinite(Number((item.location ?? item).lat)) && Number.isFinite(Number((item.location ?? item).lng))).map((item) => ({...item,distanceKm:haversine(center,{lat:Number((item.location??item).lat),lng:Number((item.location??item).lng)})})).filter((item) => item.distanceKm <= radiusKm).sort((a,b) => a.distanceKm-b.distanceKm).map((item) => ({...item,distanceKm:Number(item.distanceKm.toFixed(2))}));
const incidents = filter(body.incidents); const riskZones = filter(body.riskZones); const alerts = filter(body.alerts); const externalEvents = filter(body.externalEvents);
return [{ json: { ok: true, incidents, riskZones, alerts, externalEvents, count: incidents.length+riskZones.length+alerts.length+externalEvents.length, radiusKm, generatedAt: new Date().toISOString() } }];
